// Digi's Planting Tools: Planting Tools.
// One plugin and one settings file for all of them: F1 shows a switch per sub-mod at the top, then each sub-mod's
// settings under its name. Generated by make_combined.py; the sub-mods' code is in Modules/.
using BepInEx;
using DigiCore;

namespace DigiPlanting
{
    [BepInPlugin(Guid, Name, Version)]
    [BepInDependency("Searica.Valheim.TerrainTools", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ValheimLegends", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("cdev.equipmentslots", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("com.alan.bettersmelter", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ishid4.mods.betterarchery", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("randyknapp.mods.epicloot", BepInDependency.DependencyFlags.SoftDependency)]
    public class Plugin : DigiPlugin
    {
        public const string Guid = "digi.valheim.plantingtools";
        public const string Name = "Digi's Planting Tools";
        public const string Version = "1.1.9";

        protected override ModuleInfo[] Modules { get; } =
        {
            new ModuleInfo(typeof(global::PlantingTools.Plugin), "Planting Tools", "digi.valheim.plantingtools", "Plant a whole grid of crops, saplings or bushes with one click of the cultivator, in about a second and without lag; lines up with your fields, fills a cultivated patch, Shift+E harvests everything around you.", null, true),
            new ModuleInfo(typeof(global::PlantAnything.Plugin), "Plant Anything", "digi.valheim.plantanything", "Plant berry bushes, mushrooms, flowers, ancient, ygga, autumn birch and ashwood saplings and more with the cultivator; crops in any biome and other growing rules, regrow times, growth time on hover. Replaces Plant Everything.", null, true),
        };
    }
}
